import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.CTeY_0bQ.js";const m=JSON.parse('{"title":"维护者指南","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/maintainer.md","filePath":"guide/maintainer.md","lastUpdated":null}'),a={name:"guide/maintainer.md"};function s(i,e,r,n,l,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<div><h1 id="维护者指南" tabindex="-1">维护者指南 <a class="header-anchor" href="#维护者指南" aria-label="Permalink to &quot;维护者指南&quot;">​</a></h1><p>面向维护 laoshi 本身的人：改提示词和 skill、发布新版本、处理复盘提交的问题。</p><h2 id="_1-改动之前" tabindex="-1">1. 改动之前 <a class="header-anchor" href="#_1-改动之前" aria-label="Permalink to &quot;1. 改动之前&quot;">​</a></h2><ul><li>先看 <a href="./../reference/scope">SCOPE.md</a>：新提议须服务于&quot;帮助非专职开发的同事把一个需求从对齐做到可验收&quot;，至少有两个真实场景，并且无法通过项目配置或项目说明解决。</li><li>改动已有的设计决定（<a href="./../reference/adr/">docs/adr/</a>）时，新增一条 ADR 说明理由，并在旧的一条中注明被哪条取代。</li><li>界面的颜色、字体、组件按 <code>design/</code>（设计规范，见其中的 README）来；改了 <code>design/tokens.json</code>、<code>design/reference/components.css</code> 或 <code>design/examples/icons.js</code>，运行 <code>node scripts/tokens-build.mjs</code> 更新审查网页里的副本。</li><li>改动文件格式（spec、状态文件、结果文件、决策记录等）时，同时更新 <a href="./../reference/contracts/">contracts/</a>、代码和测试；状态文件的格式变化要加迁移（见 <code>contracts/state.md</code>）。</li></ul><h2 id="_2-改-skill-和提示词的规则" tabindex="-1">2. 改 skill 和提示词的规则 <a class="header-anchor" href="#_2-改-skill-和提示词的规则" aria-label="Permalink to &quot;2. 改 skill 和提示词的规则&quot;">​</a></h2><ul><li><strong>入口不调用入口</strong>。<code>/laoshi</code>、<code>/laoshi-setup</code>、<code>/laoshi-doctor</code>、<code>/laoshi-retro</code> 之间只能&quot;告诉用户去运行&quot;，不能互相加载。</li><li><strong>路径用占位符</strong>：skill 中引用安装目录内的文件写 <code>{{REQ_KIT_ROOT}}/...</code>，启动命令写 <code>{{PIPELINE_LAUNCHER}}</code>，版本号写 <code>{{REQ_KIT_VERSION}}</code>。安装器会替换它们；<code>npm test</code> 会检查引用的文件都存在。</li><li><strong>不写平台的名字</strong>：引擎、提示词和 skill 中和平台有关的说法写成 <code>{{platform.&lt;词&gt;}}</code>（见 <a href="./../reference/design/platform-vocabulary">platform-vocabulary</a>），整段不同的写成 <code>{{fragment.&lt;名称&gt;}}</code>，各平台的片段放在适配器里（如 <code>adapters/paseo/skill/setup.md</code>）。<code>npm test</code> 会检查这些目录中没有平台的名字；确实需要时在那一行写 <code>platform-name:</code> 说明理由。</li><li><strong>frontmatter</strong> 只用 <code>name</code>、<code>description</code>，agent 专属的放在 <code>metadata</code> 下；<code>description</code> 中不要出现半角的 <code>: </code>。</li><li><strong>手册</strong>（<code>skills/laoshi/playbooks/*.md</code>）开头必须有&quot;## 步骤&quot;编号列表，<code>/laoshi</code> 会把它原样放进待办列表；新增手册要加进 <code>/laoshi</code> 的路由表。</li><li><strong>原则</strong>：增加一条原则需要至少两次真实失误作为依据，并且无法用 CI 或配置解决；总数不超过 10 条。原则的一句话版本写进 <code>principles/INDEX.md</code>，它同时被聊天和每个步骤的提示词使用。</li><li><strong>措辞</strong>：读者是有技术背景、但不读代码的使用者（测试、产品、项目经理）。讲需求和结果，不讲代码实现。</li></ul><h2 id="_3-验证改动" tabindex="-1">3. 验证改动 <a class="header-anchor" href="#_3-验证改动" aria-label="Permalink to &quot;3. 验证改动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>改了什么</th><th>至少要做</th></tr></thead><tbody><tr><td>引擎代码</td><td><code>npm test</code>、<code>npm run typecheck</code></td></tr><tr><td>步骤提示词</td><td>上面两项 + <code>npm run eval</code>（至少跑受影响的用例），与上一次的结果对比</td></tr><tr><td>入口、手册、方法 skill、原则</td><td><code>npm test</code> + 对话评估中受影响的剧本（<code>evals/conversation/</code>）</td></tr><tr><td>安装器</td><td><code>npm test</code>（在临时 HOME 中测试），并在 Windows 上实际装一次（只用 cmd 或 Git Bash）</td></tr><tr><td>评估用例</td><td><code>npm run eval:self-check</code>（参考实现必须通过隐藏验收）</td></tr><tr><td>平台适配器</td><td><code>npm test</code>；dsh 另跑端到端检查 <code>node adapters/dsh/e2e/run-e2e.mjs --worktree</code>（见 <a href="./dsh">adapters/dsh/README.md</a>）；Paseo 另跑 <code>npm run smoke -- check</code></td></tr><tr><td>文档站点</td><td><code>cd site &amp;&amp; npm ci &amp;&amp; npm run build</code>（会检查站内链接）</td></tr></tbody></table><p>提示词改动以评估结果为准：如实率（不夸大）不能下降；隐藏验收通过率、用时、轮次与上一次对比，变差时说明原因。</p><h2 id="_4-发布" tabindex="-1">4. 发布 <a class="header-anchor" href="#_4-发布" aria-label="Permalink to &quot;4. 发布&quot;">​</a></h2><p>版本号遵循语义化版本，从 <code>0.1.0</code> 开始，标签<strong>不带 <code>v</code> 前缀</strong>（例如 <code>0.1.0</code>、<code>0.2.0-beta.1</code>）。laoshi 和 paseo-req-kit 一样通过 npm 分发：使用者用 <code>npx -y @yiyi_zhang/laoshi@latest install</code> 安装，用 <code>laoshi upgrade</code> 升级，内网通过公司的 npm 镜像取得。</p><p>开发中的版本号带 <code>-dev</code>（如 <code>0.2.0-dev</code>），不会被发布。发布一个版本：</p><ol><li>在 <code>CHANGELOG.md</code> 中把这一版写成 <code>## &lt;版本&gt; - &lt;日期&gt;</code> 一节：使用者会看到的变化在前，升级须知单独列出。发布流程用这一节作为 GitHub Release 的正文，没有这一节时停下。</li><li>把 <code>package.json</code> 的 <code>version</code> 改成这个版本（去掉 <code>-dev</code>），两个插件的版本跟着改（<code>adapters/dsh/plugin/package.json</code> 和 <code>index.mjs</code> 的 <code>VERSION</code>、<code>adapters/paseo/plugin/package.json</code>，测试会检查 Paseo 插件）；平台支持范围有变化时同时更新 <code>reqKit.paseo</code>。</li><li>跑完第 3 节中受影响的验证，并在 Windows 上实际装一次（<code>node scripts/check-package.mjs</code> 检查装出来的包）。</li><li>合并到 <code>main</code>。<code>.github/workflows/release.yml</code> 发现这个版本号还没有标签，就在这个提交上跑测试（Linux 和 Windows）、类型检查、评估自检，把文档站点构建进包里（<code>site-dist/</code>，<code>laoshi docs</code> 离线可用），<code>npm pack</code> 后用 <code>scripts/check-package.mjs</code> 按使用者的方式安装检查，再做 Windows 离线安装包。全部通过后才打上同名标签（不带 <code>v</code>），发布到 npm（预发布版用 <code>beta</code> 标签，正式版用 <code>latest</code>），并建 GitHub Release，附上 <code>.tgz</code> 和离线安装包。测试没通过时不会留下标签，把修复合到 <code>main</code> 就会用同一个版本号重新发布。</li><li>发布后把 <code>version</code> 改回下一个开发版本（如 <code>0.2.0-dev</code>）。</li></ol><p>也可以自己推送标签（<code>git push origin 0.1.0</code>）触发；重新发布已有的标签：GitHub → Actions → release → Run workflow，填版本号。npm 上发布错的版本用 <code>npm deprecate</code> 标注（npm 不允许重新发布同一版本号）。</p><p><strong>npm 发布的一次性设置</strong>：</p><ol><li>包名是带作用域的 <code>@yiyi_zhang/laoshi</code>（<code>laoshi</code> 在 npm 上不能使用），作用域 <code>yiyi_zhang</code> 就是发布者的 npm 用户名。在 npmjs.com 上用这个账号建一个 Granular Access Token：权限 Read and write，Packages 选 All packages，并勾选 <strong>Bypass two-factor authentication</strong>（CI 里没法输入一次性验证码）。在 GitHub 仓库的 Settings → Secrets and variables → Actions 中新建 secret <code>NPM_TOKEN</code>，值为这个 token。不要把 token 写进任何文件或发给别人。</li><li>第一次发布成功后，在 npmjs.com 的 <code>@yiyi_zhang/laoshi</code> 包设置 → Trusted Publisher 中添加 GitHub Actions：仓库 <code>yiyisf/laoshi</code>，工作流 <code>release.yml</code>。之后发布不再需要 token，可以删除 <code>NPM_TOKEN</code>。</li></ol><p><strong>发布到 npm 失败时</strong>：GitHub Release 和其中的 <code>.tgz</code> 照常生成，只有 npm 那一步失败。日志里是 <code>E401</code>、<code>E403</code>、<code>ENEEDAUTH</code>、<code>E404</code> 的，检查 token 或 Trusted Publisher 设置；是 <code>TLOG_CREATE_ENTRY_ERROR ... (500)</code> 的，是 sigstore 写入来源证明时出错，与设置无关，过一段时间在 Actions → release → Run workflow 填同一个版本重跑。一直失败、又急着发布时，重跑时取消勾选 <code>provenance</code>，这一次不带来源证明发布（npm 上这个版本不显示来源证明）。 3. 文档站点：Settings → Pages → Source 选 &quot;Deploy from a branch&quot;，分支 <code>gh-pages</code>，目录 <code>/</code>（<code>.github/workflows/site.yml</code> 在 main 更新时发布）。</p><p><strong>企业私有仓库</strong>：只代理 npmjs 的不用做什么。需要单独发布到内网仓库时，从 GitHub Release 下载 <code>laoshi-&lt;版本&gt;.tgz</code>（或 <code>npm pack</code> 得到 <code>yiyi_zhang-laoshi-&lt;版本&gt;.tgz</code>），执行 <code>npm publish &lt;这个文件&gt; --registry &lt;内网地址&gt; --tag &lt;同名标签&gt;</code>。完全没有 npm 镜像的环境用 GitHub Release 上的离线安装包（<code>laoshi-&lt;版本&gt;-&lt;提交&gt;-win32-x64.zip</code>，也可以自己运行 <code>node scripts/pack-intranet.mjs</code>），见<a href="./intranet">内网安装与验证</a>。</p><p><strong>对外约定</strong>：通知事件（<code>contracts/notifier-event.md</code>）由各团队自己的 IM 模块读取，同一 <code>schema</code> 内只增加字段；<code>laoshi</code> 的子命令和参数会被写进各团队的使用说明，改名时保留旧名一个主版本（<code>req</code> 是 <code>laoshi</code> 的别名）。<code>laoshi api</code> 的输出（<code>contracts/cli-json.md</code>）是插件和脚本读取的格式，同一 <code>schema</code> 内只增加字段。</p><h2 id="_5-处理复盘提交的问题" tabindex="-1">5. 处理复盘提交的问题 <a class="header-anchor" href="#_5-处理复盘提交的问题" aria-label="Permalink to &quot;5. 处理复盘提交的问题&quot;">​</a></h2><p><code>/laoshi-retro</code> 会把 laoshi 本身的问题写成报告草稿交给用户。收到后：</p><ol><li>能复现的，先加一个评估用例或对话剧本，确认它在当前版本失败。</li><li>修改后跑同一个评估，确认修好，并且其他用例没有变差。</li><li>在 CHANGELOG 中记录。</li></ol><h2 id="_6-目录速查" tabindex="-1">6. 目录速查 <a class="header-anchor" href="#_6-目录速查" aria-label="Permalink to &quot;6. 目录速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>内容</th></tr></thead><tbody><tr><td><code>skills/</code></td><td>安装到各平台的 skill（安装时按平台渲染）：入口、手册、方法、原则</td></tr><tr><td><code>principles/INDEX.md</code></td><td>原则索引</td></tr><tr><td><code>engine/src/</code></td><td>引擎：启动器、主流程、配置、状态与迁移、体检、评估运行器</td></tr><tr><td><code>engine/prompts/</code></td><td>步骤提示词（含 <code>00-shared-context.md</code> 和评审小组成员的 <code>panel-member.md</code>）</td></tr><tr><td><code>engine/test/</code></td><td>引擎测试，<code>fake-runtime.ts</code> 是模拟的平台</td></tr><tr><td><code>engine/src/builtin/</code></td><td>内置能力：<code>git worktree</code> 工作区、服务管理（平台不提供时使用）</td></tr><tr><td><code>engine/skill-fragments/</code></td><td>skill 中各平台共用的内置片段</td></tr><tr><td><code>adapters/&lt;平台&gt;/</code></td><td>平台适配器：<code>adapter.ts</code>（能力和用词）、运行时、<code>install.mjs</code>（安装器的平台部分）；dsh 另有插件 <code>plugin/</code> 和端到端检查 <code>e2e/</code>；Paseo 另有需求插件 <code>plugin/</code>（<code>laoshi plugin</code>）和迁移 <code>migrate.ts</code></td></tr><tr><td><code>bin/</code></td><td><code>laoshi</code> 命令、安装器（<code>install.mjs</code>）、一步安装（<code>bootstrap.mjs</code>）、<code>laoshi docs</code></td></tr><tr><td><code>site/</code></td><td>文档站点（VitePress）；<code>site/scripts/sync-docs.mjs</code> 把 <code>docs/guide</code>、<code>contracts</code> 等复制进站点</td></tr><tr><td><code>test/</code></td><td>安装器、体检、skill 的测试</td></tr><tr><td><code>evals/</code></td><td>评估：样例仓库、用例、对话剧本</td></tr><tr><td><code>contracts/</code></td><td>文件格式约定</td></tr><tr><td><code>docs/adr/</code></td><td>设计决定</td></tr><tr><td><code>design/</code></td><td>界面设计规范：tokens、品牌手册、各界面规范、组件、效果图</td></tr></tbody></table></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/guide/维护者指南.md">docs/guide/维护者指南.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/guide/维护者指南.md">在 GitHub 上编辑</a></p>',2)])])}const g=o(a,[["render",s]]);export{m as __pageData,g as default};
